{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound Baths & Immersive Rituals</title>
  <meta name="description" content="Playful, premium sound baths in {{CITY}}, {{STATE}}. Intensive sessions & private offerings with {{FACILITATOR_NAME}}.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="zen">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" aria-label="Primary navigation">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private</a>
        <a href="/pricing.html">Investment</a>
        <a href="/about.html">About</a>
        <a href="/faq.html">FAQ</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="wrap">
        <div class="hero-grid">
          <div>
            <h1 class="eyebrow">The intensive reset</h1>
            <h2 class="title">A deep, sensory sound bath to unwind the body and enliven the nervous system</h2>
            <p class="lead">Join {{FACILITATOR_NAME}} for a premium, sensory-first session that blends crystal bowls, chimes, and tuning forks into a guided ritual. We design sound to land gently and shift you deeply.</p>
            <p class="meta">Next gathering: <strong>{{NEXT_EVENT_DATE}}</strong></p>
            <div class="hero-actions">
              <a class="button primary" href="/events.html">See next events</a>
              <a class="button subtle" href="/book.html">Book a private session</a>
            </div>
          </div>
          <figure class="hero-art" aria-hidden="true">
            <svg viewBox="0 0 600 400" preserveAspectRatio="xMidYMid slice" class="art-svg">
              <defs>
                <linearGradient id="g1" x1="0" x2="1">
                  <stop offset="0" stop-color="#EDE7F6"/>
                  <stop offset="1" stop-color="#F3F9FF"/>
                </linearGradient>
              </defs>
              <rect width="100%" height="100%" fill="url(#g1)"></rect>
              <path d="M30 320 C130 80, 470 80, 570 320 L570 380 L30 380 Z" fill="#fff" opacity="0.06"></path>
              <g transform="translate(80,40)" opacity="0.12">
                <circle cx="50" cy="70" r="48" fill="#CDEDF7"></circle>
                <circle cx="210" cy="30" r="36" fill="#EAD7FF"></circle>
                <circle cx="330" cy="110" r="58" fill="#DFF7E3"></circle>
              </g>
            </svg>
          </figure>
        </div>
      </div>
    </section>

    <!-- DIAGNOSTIC -->
    <section class="diagnostic" id="diagnostic">
      <div class="wrap narrow">
        <h3 class="section-title">Where are you right now?</h3>
        <p class="section-lead">A quick sensory check to help you choose the right experience. This intensive model is for those ready to slow, rest, and drop into a concentrated container.</p>
        <ul class="checks">
          <li><strong>Physical:</strong> Stiff or tired? Our sessions support deep tissue relaxation.</li>
          <li><strong>Mental:</strong> Overstimulated or scattered? Intention and binaural-friendly frequencies invite focus.</li>
          <li><strong>Emotional:</strong> Want gentle release? The ritual provides somatic safety and containment.</li>
        </ul>
      </div>
    </section>

    <!-- PLAN -->
    <section class="plan" id="plan">
      <div class="wrap">
        <div class="grid">
          <div>
            <h3 class="section-title">Session flow — what to expect</h3>
            <p>Our intensive sessions follow a clear, slow arc: arrival and settling, guided breath + sound induction, deep immersive soundscape, and a gentle re-entry. Each moment is timed to support safe nervous system downshifting.</p>
            <ol class="flow">
              <li><strong>Arrival & grounding:</strong> Welcome, orientation, and a short check-in.</li>
              <li><strong>Breathwork & intention:</strong> Simple breath to attune to the space.</li>
              <li><strong>Immersion:</strong> 30–45 minutes of layered sound (you rest, we hold the field).</li>
              <li><strong>Integration:</strong> Slow return, journaling prompts, tea optional.</li>
            </ol>
            <p class="note">Instruments vary by session. Expect a curated blend such as crystal bowls, gong, chimes, and tuning forks — each gathering chooses a different palette for texture and depth.</p>
          </div>
          <aside class="side">
            <h4>What to bring</h4>
            <ul>
              <li>Yoga mat, blanket, and a pillow for extra comfort.</li>
              <li>Water bottle and an eye mask if you use one.</li>
              <li>Wear layers — we keep the room cozy but you may cool down.</li>
            </ul>
            <h4>Contraindications</h4>
            <p class="contra">If you are pregnant, have a pacemaker, epilepsy, or uncontrolled hypertension, please consult your medical provider before attending and notify the facilitator. Sound can be deep and intensive; safety first.</p>
          </aside>
        </div>
      </div>
    </section>

    <!-- MICRO HABITS -->
    <section class="micro_habits" id="micro-habits">
      <div class="wrap narrow">
        <h3 class="section-title">Pre-ritual micro-habits</h3>
        <p class="section-lead">Small practices to get the most from a session — playful, premium, and practical.</p>
        <div class="habits-grid">
          <div class="habit">
            <h5>Hydrate</h5>
            <p>Drink water earlier in the day; we recommend avoiding heavy meals right before the session.</p>
          </div>
          <div class="habit">
            <h5>Unplug</h5>
            <p>Give yourself 30 minutes of reduced screen time to begin calming the nervous system.</p>
          </div>
          <div class="habit">
            <h5>Intent</h5>
            <p>Bring a simple question or intention. Not required — but tiny intentions deepen the experience.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PRICING -->
    <section class="pricing" id="pricing">
      <div class="wrap">
        <h3 class="section-title">Offerings & investment</h3>
        <p class="section-lead">Our pricing reflects an intensive, small-group container and bespoke private work.</p>
        <div class="price-grid">
          <div class="card">
            <h4>Group Sound Bath</h4>
            <p class="price">$40 — 75 min</p>
            <p>Curated evening gatherings featuring a mix of crystal bowls and chimes. Ideal for rest and gentle recalibration.</p>
            <a class="button" href="/events.html">View schedule</a>
          </div>
          <div class="card highlight">
            <h4>Intensive Workshop</h4>
            <p class="price">$120 — 2.5 hrs</p>
            <p>Deep container including breathwork, sustained sound immersion with gong and monochord, and integration practices.</p>
            <a class="button" href="/book.html">Reserve a spot</a>
          </div>
          <div class="card">
            <h4>Private Sessions</h4>
            <p class="price">From $150 — 1:1</p>
            <p>1:1, couples, and corporate sessions are available. Instruments include tuning forks, bowls, and bespoke field design.</p>
            <a class="button" href="/private-sessions.html">Private options</a>
          </div>
        </div>
        <p class="fineprint">All sessions require online pre-registration. Group sizes are intentionally small to keep the field intimate.</p>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta" id="cta">
      <div class="wrap narrow">
        <h3>Ready to book your reset?</h3>
        <p>If you have questions about suitability or instruments used, reach out — we're playful, thorough, and here to hold the space.</p>
        <div class="cta-actions">
          <a class="button primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="button subtle" href="/contact.html">Contact us</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-grid">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <p class="muted">{{TAGLINE}}</p>
        </div>
        <div>
          <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
          <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
        <div>
          <p>Venue: {{VENUE_NAME}}, {{CITY}}, {{STATE}}</p>
        </div>
      </div>
      <p class="copyright">© {{BUSINESS_NAME}} • All rights reserved.</p>
    </div>
  </footer>

</body>
</html>"} 
