{"path":"assets/css/styles.css","content":"/* Zen Minimal — playful premium palette */
:root{
  --bg:#FBFDFF;
  --card:#FFFFFF;
  --muted:#7B8794;
  --accent-1:#6C63FF;
  --accent-2:#00B4D8;
  --glass:rgba(255,255,255,0.6);
  --shadow:0 8px 30px rgba(12,18,30,0.06);
  --radius:14px;
  --max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body.zen{font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:#0d1b2a;background:linear-gradient(180deg,var(--bg),#F7FBFF 60%);background-attachment:fixed;margin:0}
.wrap{max-width:var(--max);margin:0 auto;padding:36px}
.wrap.narrow{max-width:900px}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.5));box-shadow:var(--shadow);z-index:20}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:#0b1220;text-decoration:none;font-size:18px}
.nav a{margin-left:18px;color:#17212b;text-decoration:none;font-weight:600}
.nav a.cta{background:linear-gradient(90deg,var(--accent-1),var(--accent-2));color:white;padding:10px 14px;border-radius:10px}
.hero{padding:64px 0 40px;background-image:url('../img/pattern.svg');background-repeat:repeat;}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center}
.eyebrow{color:var(--muted);text-transform:uppercase;letter-spacing:1px;font-size:13px;margin:0 0 8px}
.title{font-size:36px;margin:0 0 12px}
.lead{color:#102231;margin:0 0 14px}
.meta{color:var(--muted);margin-bottom:18px}
.hero-actions .button{margin-right:10px}
.button{display:inline-block;padding:10px 16px;border-radius:12px;text-decoration:none;border:1px solid rgba(13,27,42,0.05);background-color:var(--card);color:#072033}
.button.primary{background:linear-gradient(90deg,var(--accent-1),var(--accent-2));color:white;box-shadow:0 8px 24px rgba(108,99,255,0.18)}
.button.subtle{background:transparent;border:1px solid rgba(7,18,28,0.06)}
.hero-art{width:100%;height:100%;max-height:360px;border-radius:14px;overflow:hidden;box-shadow:var(--shadow)}
.diagnostic{padding:36px 0}
.section-title{margin:0 0 12px;font-size:20px}
.section-lead{color:var(--muted);margin:0 0 18px}
.checks{list-style:none;padding:0;margin:0}
.checks li{padding:10px 0;border-top:1px dashed rgba(15,25,38,0.04)}
.plan{padding:36px 0}
.grid{display:grid;grid-template-columns:1fr 320px;gap:28px}
.side{background:linear-gradient(180deg,var(--glass),rgba(255,255,255,0.4));padding:18px;border-radius:12px;box-shadow:var(--shadow)}
.side h4{margin:0 0 10px}
.flow{padding-left:18px}
.contra{color:#7B2D2D;background:#FFF2F2;padding:8px;border-radius:8px}
.micro_habits{padding:36px 0}
.habits-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.habit{background:var(--card);padding:14px;border-radius:12px;box-shadow:0 6px 20px rgba(3,12,26,0.04)}
.pricing{padding:36px 0}
.price-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.card{background:linear-gradient(180deg,#fff,#fbfdff);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
.card.highlight{border:1px solid rgba(108,99,255,0.12)}
.price{font-size:20px;margin:8px 0;font-weight:700}
.fineprint{color:var(--muted);margin-top:12px}
.cta{padding:36px 0;text-align:center}
.cta-actions .button{margin:6px}
.site-footer{border-top:1px solid rgba(6,16,30,0.04);margin-top:36px;padding:24px 0;background:transparent}
.foot-grid{display:flex;justify-content:space-between;gap:12px}
.muted{color:var(--muted)}
@media(max-width:880px){
  .hero-grid{grid-template-columns:1fr;}
  .grid{grid-template-columns:1fr}
  .price-grid{grid-template-columns:1fr}
  .habits-grid{grid-template-columns:1fr}
  .nav{display:none}
  .site-header .wrap{justify-content:space-between}
}
/* subtle animated dots using the svg pattern as background for texture */
.zenspark{position:relative}
.zenspark:after{content:'';position:absolute;inset:0;background-image:radial-gradient(circle at 20% 30%,rgba(108,99,255,0.04),transparent 8%),radial-gradient(circle at 80% 70%,rgba(0,180,216,0.03),transparent 10%);pointer-events:none}"} 
{"path":"assets/js/main.js","content":"// Minimal interactions for the zen minimal sound bath site
document.addEventListener('DOMContentLoaded',function(){
  // Smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var id = this.getAttribute('href').slice(1);
      var el = document.getElementById(id);
      if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
    });
  });

  // Simple accessible toggle for card details (if any)
  document.querySelectorAll('.card').forEach(function(card){
    card.addEventListener('click',function(e){
      // clicking a card highlights it for attention
      document.querySelectorAll('.card').forEach(function(c){c.classList.remove('active')});
      card.classList.add('active');
    });
  });

  // small utility: replace NEXT_EVENT_DATE placeholders if present in data-* attributes
  var nextDate = document.body.getAttribute('data-next-event');
  if(nextDate){
    document.querySelectorAll('*').forEach(function(node){
      if(node.childNodes && node.childNodes.length){
        node.childNodes.forEach(function(n){
          if(n.nodeType===3 && n.nodeValue && n.nodeValue.indexOf('{{NEXT_EVENT_DATE}}')>-1){
            n.nodeValue = n.nodeValue.replace(/\{\{NEXT_EVENT_DATE\}\}/g,nextDate);
          }
        });
      }
    });
  }
});"} 
